usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.List(
		context.TODO(),
		openai.EvalListParams{
			After: param.NewOpt[string]("after"),
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.EvalsListOrder](openai.EvalsListOrderAsc),
			OrderBy: param.NewOpt[openai.EvalsListOrderBy](openai.EvalsListOrderByCreatedAt),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
